testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Produto } from './solution.mjs';

test('inicializa os três campos', () => {
  const produto = new Produto('Caderno', 12.5, 3);
  assert.equal(produto.nome, 'Caderno');
  assert.equal(produto.preco, 12.5);
  assert.equal(produto.quantidade, 3);
});

test('quantidade padrão é 1 quando omitida', () => {
  const produto = new Produto('Caneta', 2);
  assert.equal(produto.quantidade, 1);
});

test('recusa nome vazio e preço negativo', () => {
  assert.throws(() => new Produto('', 5));
  assert.throws(() => new Produto('   ', 5));
  assert.throws(() => new Produto('Caneta', -1));
});

test('recusa quantidade inválida', () => {
  assert.throws(() => new Produto('Caneta', 2, 0));
  assert.throws(() => new Produto('Caneta', 2, '2'));
});

solutionCode:
// O molde do produto: o objeto nasce completo e validado.
export class Produto {
  constructor(nome, preco, quantidade = 1) {
    // Portaria de entrada: nome precisa ser texto não vazio.
    if (typeof nome !== 'string' || nome.trim() === '') {
      throw new Error('nome precisa ser um texto não vazio');
    }
    // Preço não pode ser negativo.
    if (typeof preco !== 'number' || preco < 0) {
      throw new Error('preco precisa ser um número não negativo');
    }
    // Quantidade (padrão 1) precisa ser maior ou igual a 1.
    if (typeof quantidade !== 'number' || quantidade < 1) {
      throw new Error('quantidade precisa ser um número maior ou igual a 1');
    }
    this.nome = nome;
    this.preco = preco;
    this.quantidade = quantidade;
  }
}
